mapper.select:
select a.cmpycd, a.deptcd, a.deptnm, a.deptsnm, ifnull(a.deptenm,'') as deptenm, a.updept, ifnull(a.deptdum, '') as deptdum, ifnull(a.deptemp, '') as deptemp, a.frymd, a.toymd, a.taxunit, a.costgbn, a.dspord, 0 as lev, ifnull(c.deptnm, '') as updeptnm, ifnull(d.usernm, '') as empnm from haba120t_tbl a left outer join haba120t_tbl c on a.cmpycd = c.cmpycd and a.updept = c.deptcd left outer join haba920t_tbl d on a.cmpycd = d.cmpycd and a.deptemp = d.userid where a.cmpycd = #{cmpycd}
and a.deptnm like concat('%', trim(#{deptnm}), '%')
order by a.dspord

mapper.delete:
DELETE FROM haba120t_tbl
 WHERE cmpycd   = #{cmpycd}
   AND deptcd   = #{deptcd}

choose.when:
UPDATE haba910t_tbl
   SET updemp  = #{updemp}, logoimg = #{logoimg}
 WHERE cmpycd  = #{cmpycd};

SELECT 'OK' AS RESULT, '' AS MSG;

UPDATE haba910t_tbl
   SET updemp  = #{updemp}, stampimg = #{stampimg}
 WHERE cmpycd  = #{cmpycd};

SELECT 'OK' AS RESULT, '' AS MSG;

DELETE FROM haba910t_tbl
 WHERE cmpycd  = #{cmpycd};

SELECT 'OK' AS RESULT, '' AS MSG;

mapper.select:
select  a.cmpycd,   a.userid,   a.usernm,   a.deptcd,   a.deptnm,
        a.pw,       a.telno,    a.hpno,     a.email,
        a.useyn,    a.pricegbn, a.photo_path, a.inner_no
  from  haba920t_tbl a
 where a.cmpycd  = #{cmpycd}
   and a.userid  = #{userid}

mapper.delete:
DELETE FROM haba920t_tbl
 WHERE cmpycd = #{cmpycd}
   AND userid = #{userid}

mapper.select:
select a.pgmid, a.pgmnm, ifnull(b.useyn,'N') as useyn,
       ifnull(b.dspord, a.dspord) as dspord, ifnull(b.mypgm,'N') as mypgm
  from haaa800t_tbl a left outer join haba935t_tbl b
    on a.pgmid  = b.pgmid
   and a.useyn   = 'Y'
   and b.cmpycd = #{cmpycd}
   and b.usergrp = #{usergrp}
 where a.upmucd  = #{upmucd}
   and a.grpcd   = #{grpcd}
   and a.useyn   = 'Y'
 order by ifnull(b.dspord, a.dspord)

mapper.delete:
DELETE FROM haba935t_tbl
 WHERE cmpycd  = #{cmpycd}
   and usergrp = #{usergrp}
   and upmucd  = #{upmucd}
   and grpcd   = #{grpcd}
   and pgmid   = #{pgmid}
